import pathlib,json,hashlib,base64
P=pathlib.Path('docs/iterations/I05/d2-canonical-interface-design')
R=pathlib.Path('docs/reviews/I05/d2-canonical-interface-design')
def load(p):return json.loads(p.read_text())
def need(x,m):
 if not x:raise AssertionError(m)
def C(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode('utf-8')
identity=load(R/'input-identity.json');facts=R/'fixed-inputs';api=load(facts/'api-layouts.json');additional=load(facts/'additional-return-layouts.json');recipes=load(facts/'digest-recipes.json');bridge=load(P/'field-codec-bridge.json');digest=load(P/'digest-bridge.json');grammar=load(P/'proposed-export-grammar.json');requests=load(P/'authority-and-requests.json');examples=load(P/'hand-examples.json');acceptance=load(P/'acceptance-map.json')
need(len(identity['protectedInventory'])==176,'old176 inventory')
for x in identity['protectedInventory']:
 b=pathlib.Path(x['path']).read_bytes();need(len(b)==x['bytes'] and hashlib.sha256(b).hexdigest()==x['sha256'],'old176 frozen bytes')
need(len(identity['fixedAllowlistInputs'])==11,'exact11')
for x in identity['fixedAllowlistInputs']:
 b=pathlib.Path(x['snapshot']).read_bytes();need(len(b)==x['bytes'] and hashlib.sha256(b).hexdigest()==x['sha256'],'fixed11 snapshot integrity')
need(len(api['layouts'])==bridge['inputApiTopLevelCount']==12,'12 not invented13')
need(len(additional['records'])==bridge['additionalReturnRecordCount']==15,'15 return declarations')
dirs={d['id']:d for d in bridge['directories']};rows={x['id']:x for x in bridge['fieldRows']}
need(len(dirs)==len(bridge['directories'])==52 and len(rows)==len(bridge['fieldRows'])==bridge['fieldRowCount']==263,'unique full field directories/rows')
for d in dirs.values():
 names=d['orderedFields'];actual=[x['field'] for x in bridge['fieldRows'] if x['layout']==d['id']];need(actual==names,'complete original field order '+d['id'])
 for name in names:need(d['id']+'/'+name in rows,'every field exact mapping')
for j,d in enumerate(api['layouts']):need(dirs['api:'+d['id']]['orderedFields']==d['orderedKeys'],'all12 original API keys')
for j,d in enumerate(api['classAnnotationIndex']):
 for f in d['annotatedFields']:need(rows['decl:'+d['source']['function']+'/'+f['name']]['existingAnnotation']==f['annotation'],'annotation verbatim')
for j,d in enumerate(additional['records']):
 name='return:'+d['class'];need(dirs[name]['orderedFields']==[f['name'] for f in d['staticallyExpandedInheritedFields']],'inherited field directory')
 for f in d['staticallyExpandedInheritedFields']:
  r=rows[name+'/'+f['name']];need(r['existingAnnotation']==f['typeAnnotation'] and r['defaultExpressionOnly']==f['defaultSyntax'],'field annotation/default expression verbatim')
need(len(dirs['return:ProfileComputation']['orderedFields'])==14 and len(dirs['return:ProfileExplanationComputation']['orderedFields'])==15,'14/15 inherited')
need(len(dirs['return:RootRef']['orderedFields'])==5 and rows['return:RootRef/kind']['existingAnnotation']=='str','RootRef5 kind str no enum')
need(dirs['return:ReadonlySequence']['orderedFields']==['native_kind','items'],'native_kind retained')
need(len(dirs['return:DirectStepsReceipt']['orderedFields'])==11 and dirs['return:DirectStepsReceipt']['orderedFields'][-1]=='retention_owner','line81 full receipt')
for name,count in [('legacy-source',4),('legacy-provenance',13),('legacy-reason',5)]:need(len(dirs['api:'+name]['orderedFields'])==count,'legacy full keys')
for name in ['Variable','Triple','Comparison','RuleSpec','ProfileLimits']:need('helper:'+name not in dirs,'do not fabricate missing directory '+name)
need(rows['helper:Number/negative_zero']['existingAnnotation'] is None,'do not infer type from name')
need(digest['existingRecipeCount']==len(recipes['recipes'])==16,'all original recipes')
need([b['existingRecipe'] for b in digest['bridges'][:16]]==recipes['recipes'],'full old recipe values unchanged')
need(digest['scopeJsonOptionsFact']['allow_nanExplicitlySpecified'] is False and digest['profileJsonOptionsFact']['allow_nan'] is False,'distinct old encoder options')
need(digest['rowsRecipeFact']['unit']=='Python characters','old slice unit')
impl=next(x for x in digest['bridges'] if x['id']=='implementation-expression');need(impl['actualDependencyLockHash'] is None and impl['existingExpressionNotEvaluated']=='hashlib.sha256(LOCK_FILE.read_bytes()).hexdigest()','expression not evaluated')
def refs(t):
 if isinstance(t,dict):
  if set(t)=={'ref'}:need(t['ref'] in grammar['definitions'],'all new refs resolve')
  for v in t.values():refs(v)
 elif isinstance(t,list):
  for v in t:refs(v)
for name,d in grammar['definitions'].items():
 need(d['status']=='NEW-PROPOSED-NOT-ADOPTED','all new grammar marked proposal')
 if d['kind']=='exact-record':need(d['required']==list(d['fields']) and d['additionalProperties'] is False,'new exact field definition')
 refs(d)
need(all(v is False for v in grammar['currentGateState'].values()),'grammar gates false')
need({r['id'] for r in requests['requests']}=={'Q01','Q02','Q03','Q04','Q05','Q06','Q07','Q08','Q09'},'precise9 requests')
need(all(r['actualReceivedPin'] is None and r['sourceFollowingAuthorized'] is False for r in requests['requests']),'no actual new permissions')
need(all(v is False for v in requests['gateState'].values()),'all actual gates false')
need(requests['roleLinkPolicyReception']['bodyRead'] is False and requests['roleLinkPolicyReception']['ref']=='3ddce89309c33e732e69f4ae668699ace6ffc13c','role reception only, no policy body read')
root=examples['rootRef']['value'];need(list(root)==dirs['return:RootRef']['orderedFields'] and type(root['kind']) is str and root['kind']=='owner-specific-unrefined-token','RootRef hand example no enum')
need('fields' not in examples['productionStyleOnly'] and list(examples['probeStyleOnly'])==['recordType','fields'],'production flat vs probe nested')
e=examples['rowsCharacterUnit'];need(len(e['inputText'])==8194 and [len(r[0]) for r in e['rows']]==[8192,2] and ''.join(r[0] for r in e['rows'])==e['inputText'],'all row character slices/tail')
need(len(e['rows'][0][0].encode('utf-8'))==e['expectedFirstRowUtf8Bytes']==16385,'character vs byte difference')
h=examples['originalDigestAndProposedRelation'];b=base64.b64decode(h['oldLiteralPreimageBase64'],validate=True);need(b==b'[]' and len(b)==h['oldLiteralRawBytes'] and hashlib.sha256(b).hexdigest()==h['oldLiteralRawSha256'],'pure literal original rawSHA')
pre=b'ontolearn/i05/canonical-interface-bridge/1-proposal\0'+C(h['relationCore']);need(pre==base64.b64decode(h['newRelationPreimageBase64'],validate=True) and hashlib.sha256(pre).hexdigest()==h['newRelationSha256'] and h['newRelationSha256']!=h['oldLiteralRawSha256'],'separate proposed relation domain exact preimage')
dto=examples['completePendingDtoExample'];need(list(dto)==grammar['definitions']['DtoEnvelope']['required'],'new DTO exact required fields')
need([x['name'] for x in dto['fieldEntries']]==dirs[dto['directoryId']]['orderedFields'],'complete source4 fields even blocked')
need(dto['wholeValueExportComplete'] is False and dto['semanticCompatible'] is False and dto['authorityVerified'] is False,'no false total completeness')
need(all(x['slot']['state']=='layout-blocked' and x['slot']['availableOriginalBlobs']==[] and x['slot']['noWireReason']=='original-api-no-dedicated-wire' for x in dto['fieldEntries']),'do not invent dedicated original bytes')
need(examples['originalDigestAndProposedRelation']['actualPreimageOrAuthorityVerified'] is False,'literal example not actual preimage proof')
need(len(acceptance['negativeDesignCases'])==21,'21 DECLARED design negative cases, not product executions')
print(json.dumps({'scope':'minimal documentation/static+hand literal checks only','fixedPureInputs':11,'protectedOldCurrentBytes':176,'apiTopIds':12,'additionalReturnRecords':15,'mappedDirectories':52,'mappedFieldRows':263,'originalRecipesPreserved':16,'newProposedDefinitions':len(grammar['definitions']),'ownerRequests':9,'negativeDesignCasesDeclared':21,'negativeProductCasesExecuted':0,'handRowsChars':[8192,2],'oldCodecsOrProductsExecuted':False,'jsonSchemaEngineValidation':False,'actualAuthorityOrRuntimeClosed':False,'independentReview':'pending'},ensure_ascii=False))
